<form method="get" action="<?= site_url('news') ?>" class="row g-2 my-4" role="search">
    <div class="col-md-4"><label class="visually-hidden" for="news-query"><?= esc(lang('MCMS.common.search')) ?></label><input id="news-query" class="form-control" type="search" name="q" maxlength="120" value="<?= esc($query ?? '', 'attr') ?>" placeholder="<?= esc(lang('MCMS.common.search'), 'attr') ?>"></div>
    <div class="col-md-3"><label class="visually-hidden" for="news-filter-category"><?= esc(lang('News.Admin.category')) ?></label><select id="news-filter-category" class="form-select" name="category"><option value=""><?= esc(lang('News.Admin.allCategories')) ?></option><?php foreach ($categories ?? [] as $category): ?><option value="<?= (int) $category['id'] ?>" <?= (int) ($categoryId ?? 0) === (int) $category['id'] ? 'selected' : '' ?>><?= esc($category['name']) ?></option><?php endforeach ?></select></div>
    <div class="col-md-3"><label class="visually-hidden" for="news-filter-tag"><?= esc(lang('MCMS.content.tags')) ?></label><select id="news-filter-tag" class="form-select" name="tag"><option value=""><?= esc(lang('News.Admin.allTags')) ?></option><?php foreach ($tags ?? [] as $name): ?><option value="<?= esc($name, 'attr') ?>" <?= ($tag ?? '') === $name ? 'selected' : '' ?>><?= esc($name) ?></option><?php endforeach ?></select></div>
    <div class="col-md-2"><button class="btn btn-primary w-100" type="submit"><?= esc(lang('MCMS.common.search')) ?></button></div>
    <?php if (($query ?? '') !== '' || ($categoryId ?? null) !== null || ($tag ?? '') !== ''): ?><div><a href="<?= site_url('news') ?>"><?= esc(lang('MCMS.common.clear')) ?></a></div><?php endif ?>
</form>
